    const samples = {
      en: "Hello farmer! Your crop is being analyzed. Borcelle Agri is here to protect your harvest.",
      hi: "नमस्ते किसान! आपका फसल विश्लेषण तैयार है। बोर्सेल कृषि आपकी फसल की रक्षा करेगी।",
      mr: "नमस्कार शेतकरी! तुमचे पीक विश्लेषण तयार आहे. बोर्सेल शेती तुमच्या पिकाचे रक्षण करेल."
    };
    window.speechSynthesis.cancel();
    const utt = new SpeechSynthesisUtterance(samples[lang] || samples.en);
    utt.lang = vm[lang] || "en-IN";
    utt.rate = ttsSpeed;
    utt.pitch = 1;
    utt.volume = 1;
    const voices = window.speechSynthesis.getVoices();
    const match = voices.find(v => v.lang.startsWith((vm[lang] || "en-IN").split('-')[0]));
    if (match) utt.voice = match;
    window.speechSynthesis.speak(utt);
